package dev.elpsy.ticket;
import dev.elpsy.ticket.inventory.*;
import dev.elpsy.ticket.inventory.StockReturnStaffService.*;
import dev.elpsy.ticket.orders.*;
import dev.elpsy.ticket.orders.OrderModels.*;
import dev.elpsy.ticket.common.ApiErrors.Problem;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false","ticket.stock-return.enabled=true","ticket.admission.namespace=encore-demo-increment-return-staff"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockReturnStaffIntegrationTest {
 @Autowired ApplicationContext context;@Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;
 @Autowired StockReturnStaffService staff;@Autowired StockReturnService returns;@Autowired StockProjectionService projections;
 @Autowired StockHoldService holds;@Autowired StockSettlementService settlement;@Autowired PurchaseService purchases;@Autowired OrderService orders;
 @Autowired PlatformTransactionManager transactions;
 CommitCursorFixture fixtures;Set<String> keys=new HashSet<>();String manager="return-staff-"+UUID.randomUUID();
 record Returned(CommitCursorFixture.Fixture f,UUID order){}
 @BeforeAll void setup(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));fixtures=new CommitCursorFixture(context);db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 Returned returned(boolean extra,boolean expired){var f=fixtures.accepted(extra);keys.add(fixtures.ledger.key(f.ticket(),1));keys.add(fixtures.experiment.cursorKey(f.ticket(),1));assertTrue(purchases.process(f.event()));assertEquals("COMMITTED",settlement.reconcile(f.intent()).resolution());UUID order=db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,f.intent());if(expired){db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() clock) UPDATE ticket_order SET created_at=clock-interval '11 minutes',expires_at=clock-interval '1 minute' FROM stamp WHERE id=?",order);assertTrue(orders.expire(order));}else orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));return new Returned(f,order);}
 Returned returned(){return returned(false,false);}
 Begin body(){return new Begin(UUID.randomUUID(),3);}
 Receipt submit(Returned r,Begin b){keys.add(fixtures.ledger.key(r.f().ticket(),2));return staff.submit(manager,r.f().ticket(),r.order(),b);}
 int count(UUID request,String table){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE request_id=?",Integer.class,request);}
 void problem(String code,Runnable action){assertEquals(code,assertThrows(Problem.class,action::run).code);}
 String other(String role){String n="return-other-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),n,"unused synthetic hash",role);return n;}
 void fault(UUID request,String state){db.execute("ALTER TABLE stock_return_staff_audit ADD CONSTRAINT staff_return_fault CHECK(request_id<>'"+request+"'::uuid OR state<>'"+state+"') NOT VALID");}
 void unfault(){db.execute("ALTER TABLE stock_return_staff_audit DROP CONSTRAINT staff_return_fault");}
 @Test void managerCommitsThreeCheckpointsAndNewSpendableEpoch(){var r=returned();var old=redis.opsForHash().entries(fixtures.ledger.key(r.f().ticket(),1));var receipt=submit(r,body());assertEquals("APPLIED",receipt.state());assertEquals(2,receipt.generation());assertEquals(3,receipt.version());assertFalse(receipt.canResume());assertEquals(3,count(receipt.requestId(),"stock_return_staff_audit"));assertEquals(1,count(receipt.requestId(),"stock_return_ack"));var h=holds.prepare(r.f().owner(),new Place(UUID.randomUUID(),r.f().ticket(),1,1,1200));assertEquals("HELD",holds.apply(h.id()).state());assertEquals(3,fixtures.ledger.snapshot(r.f().ticket(),2).snapshot().available());assertEquals(old,redis.opsForHash().entries(fixtures.ledger.key(r.f().ticket(),1)));}
 @Test void expiryIsAnOriginalCandidateAndCompletesSameHandoff(){var r=returned(false,true);var c=staff.candidates(manager,r.f().ticket(),1,12).items().getFirst();assertEquals("EXPIRED",c.orderStatus());assertTrue(c.canBegin());assertEquals("APPLIED",submit(r,body()).state());}
 @Test void originalTerminalReplayDoesNotReseedLostKeyOrCertifyCurrentReady(){var r=returned();var b=body();var out=submit(r,b);redis.delete(fixtures.ledger.key(r.f().ticket(),2));orders.place(r.f().owner(),new Place(UUID.randomUUID(),r.f().ticket(),1,1,1200));var replay=submit(r,b);assertEquals("APPLIED",replay.state());assertEquals("DIRTY",replay.currentState());assertEquals(out.version(),replay.version());assertFalse(redis.hasKey(fixtures.ledger.key(r.f().ticket(),2)));}
 @Test void actorBodyTicketOrderAndNewUuidCannotAdoptEffect(){var r=returned();var b=body();submit(r,b);problem("REQUEST_CONFLICT",()->staff.submit(other("MANAGER"),r.f().ticket(),r.order(),b));problem("REQUEST_CONFLICT",()->submit(r,new Begin(b.requestId(),2)));problem("REQUEST_CONFLICT",()->submit(r,body()));var other=returned();problem("REQUEST_CONFLICT",()->staff.submit(manager,other.f().ticket(),other.order(),b));problem("NOT_FOUND",()->staff.progress(other("MANAGER"),b.requestId()));}
 @Test void viewerReadsCandidatesButCannotWriteOrReadAnotherActorsReceipt(){var r=returned();String viewer=other("VIEWER");assertFalse(staff.candidates(viewer,r.f().ticket(),1,12).items().getFirst().canBegin());problem("FORBIDDEN",()->staff.submit(viewer,r.f().ticket(),r.order(),body()));var b=body();submit(r,b);problem("NOT_FOUND",()->staff.progress(viewer,b.requestId()));assertNull(staff.candidates(viewer,r.f().ticket(),1,12).items().getFirst().ownRequestId());}
 @Test void downgradeAllowsOwnedReadButDeniesMutationBetweenPhases(){var r=returned();var b=body();fault(b.requestId(),"APPLIED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}var before=redis.opsForHash().entries(fixtures.ledger.key(r.f().ticket(),2));db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertFalse(staff.progress(manager,b.requestId()).canResume());problem("FORBIDDEN",()->submit(r,b));assertEquals(before,redis.opsForHash().entries(fixtures.ledger.key(r.f().ticket(),2)));assertEquals("CLOSED",projections.inspect(r.f().ticket()).state());}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}assertEquals("APPLIED",submit(r,b).state());}
 @Test void disabledActorCannotReadOrResumeOriginalOperation(){var r=returned();var b=body();submit(r,b);db.update("UPDATE staff_account SET enabled=false WHERE username=?",manager);try{problem("FORBIDDEN",()->staff.progress(manager,b.requestId()));problem("FORBIDDEN",()->submit(r,b));}finally{db.update("UPDATE staff_account SET enabled=true WHERE username=?",manager);}}
 @Test void flagOffHasNoFreshWritesAndKeepsPendingPgOnly(){var r=returned();var b=body();fault(b.requestId(),"APPLIED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}var off=new StockReturnStaffService(db,returns,projections,transactions,false);var p=off.progress(manager,b.requestId());assertEquals("CLOSED",p.state());assertFalse(p.canResume());assertEquals(p,off.submit(manager,r.f().ticket(),r.order(),b));var other=returned();problem("RETURN_DISABLED",()->off.submit(manager,other.f().ticket(),other.order(),body()));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_return_staff_command WHERE order_id=?",Integer.class,other.order()));}
 @Test void flagOffStillReplaysOwnedTerminalWithoutRedis(){var r=returned();var b=body();submit(r,b);var off=new StockReturnStaffService(db,returns,projections,transactions,false);redis.delete(fixtures.ledger.key(r.f().ticket(),2));assertEquals("APPLIED",off.submit(manager,r.f().ticket(),r.order(),b).state());}
 @Test void sixConcurrentOriginalSubmitsProduceOneEffectAndThreeAudits()throws Exception{var r=returned();var b=body();keys.add(fixtures.ledger.key(r.f().ticket(),2));try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Receipt>>();for(int n=0;n<6;n++)jobs.add(()->staff.submit(manager,r.f().ticket(),r.order(),b));for(var f:pool.invokeAll(jobs))assertEquals("APPLIED",f.get().state());}assertEquals(3,count(b.requestId(),"stock_return_staff_audit"));assertEquals(2,projections.inspect(r.f().ticket()).generation());}
 @Test void registrationAuditRollbackLeavesNoOperatorOrDomainCommand(){var r=returned();var b=body();fault(b.requestId(),"REGISTERED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}assertEquals(0,count(b.requestId(),"stock_return_staff_command"));assertEquals(0,count(b.requestId(),"stock_return_command"));assertEquals(1,projections.inspect(r.f().ticket()).generation());}
 @Test void closedAuditRollbackIncludesDomainCommandAndGeneration(){var r=returned();var b=body();fault(b.requestId(),"CLOSED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}assertEquals("REGISTERED",staff.progress(manager,b.requestId()).state());assertEquals(0,count(b.requestId(),"stock_return_command"));assertEquals(0,count(b.requestId(),"stock_rebuild_command"));assertEquals(1,projections.inspect(r.f().ticket()).generation());assertEquals("APPLIED",submit(r,b).state());}
 @Test void appliedStaffAuditRollbackRollsBackDomainAckReadyAndDomainAudit(){var r=returned();var b=body();fault(b.requestId(),"APPLIED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}assertEquals("CLOSED",staff.progress(manager,b.requestId()).state());assertEquals("CLOSED",projections.inspect(r.f().ticket()).state());assertEquals(0,count(b.requestId(),"stock_return_ack"));assertEquals(1,count(b.requestId(),"stock_return_audit"));assertEquals(RedisTicketLedger.Phase.OPEN,fixtures.ledger.snapshot(r.f().ticket(),2).snapshot().phase());assertEquals("APPLIED",submit(r,b).state());assertEquals(3,count(b.requestId(),"stock_return_staff_audit"));}
 @Test void sourceAdvanceIsAuditedBlockedAndCannotReplaceIdentity(){var r=returned();orders.place(r.f().owner(),new Place(UUID.randomUUID(),r.f().ticket(),1,1,1200));var b=body();var out=submit(r,b);assertEquals("BLOCKED",out.state());assertEquals("STOCK_CHANGED",out.failure());assertEquals(1,projections.inspect(r.f().ticket()).generation());assertEquals("BLOCKED",submit(r,b).state());problem("REQUEST_CONFLICT",()->submit(r,body()));}
 @Test void generationAdvanceBetweenPhasesBlocksOriginalWithoutRedisSeed(){var r=returned();var b=body();fault(b.requestId(),"APPLIED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}var other=projections.begin(r.f().ticket(),UUID.randomUUID(),3);keys.add(fixtures.ledger.key(r.f().ticket(),3));var out=submit(r,b);assertEquals("BLOCKED",out.state());assertEquals("GENERATION_FENCED",out.failure());assertEquals(0,count(b.requestId(),"stock_return_ack"));assertFalse(redis.hasKey(fixtures.ledger.key(r.f().ticket(),3)));}
 @Test void activeIntentBlocksDomainButKeepsOriginalOperatorEvidence(){var r=returned(true,false);var out=submit(r,body());assertEquals("BLOCKED",out.state());assertEquals("ACTIVE_STOCK_INTENTS",out.failure());assertEquals(2,out.version());assertEquals(0,count(out.requestId(),"stock_return_command"));}
 @Test void internalReturnCannotBeRelabeledAsNewStaffOperation(){var r=returned();var c=returns.begin(UUID.randomUUID(),r.order(),3);keys.add(fixtures.ledger.key(r.f().ticket(),2));problem("REQUEST_CONFLICT",()->submit(r,new Begin(c.requestId(),3)));problem("REQUEST_CONFLICT",()->submit(r,body()));assertFalse(staff.candidates(manager,r.f().ticket(),1,12).items().getFirst().canBegin());}
 @Test void historicalDomainAckCanCheckpointOriginalStaffProgressPgOnly(){var r=returned();var b=body();fault(b.requestId(),"APPLIED");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(r,b));}finally{unfault();}returns.reconcile(b.requestId());redis.delete(fixtures.ledger.key(r.f().ticket(),2));var out=submit(r,b);assertEquals("APPLIED",out.state());assertFalse(redis.hasKey(fixtures.ledger.key(r.f().ticket(),2)));assertEquals(3,out.version());}
 @Test void malformedOriginNeverConsumesOperatorEffectSlot(){var r=returned();problem("RETURN_ORIGIN_REQUIRED",()->submit(r,new Begin(UUID.randomUUID(),2)));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_return_staff_command WHERE order_id=?",Integer.class,r.order()));}
 @Test void immutableAuditProgressAndExactDomainProofCannotBeForged(){var r=returned();var b=body();submit(r,b);for(String table:List.of("stock_return_staff_command","stock_return_staff_audit")){assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE "+table+" SET request_id=request_id WHERE request_id=?",b.requestId()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM "+table+" WHERE request_id=?",b.requestId()));}assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_return_staff_progress SET version=version+1 WHERE request_id=?",b.requestId()));}
 @Test void boundedReadsMissingRecordsAndOuterTransactionDoNotWrite(){problem("INVALID_INPUT",()->staff.candidates(manager,UUID.randomUUID(),1,21));problem("INVALID_INPUT",()->staff.audit(manager,UUID.randomUUID(),0,12));problem("NOT_FOUND",()->staff.progress(manager,UUID.randomUUID()));problem("NOT_FOUND",()->staff.candidates(manager,UUID.randomUUID(),1,12));var r=returned();new TransactionTemplate(transactions).executeWithoutResult(tx->assertThrows(IllegalStateException.class,()->submit(r,body())));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_return_staff_command WHERE order_id=?",Integer.class,r.order()));}
}
